import { formatPrice } from '../utils'

type Item = { id: number; name: string; price: number }
type CartProps = { items: Item[] }

export function Cart({ items }: CartProps) {
  return (
    <ul>
      {items.map(item => (
        <li key={item.id}>
          {item.name} <span>{formatPrice(item.price)}</span>
        </li>
      ))}
    </ul>
  )
}
